package net.portswigger.mcp.tools

import io.modelcontextprotocol.kotlin.sdk.server.Server
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

internal const val SCREENSHOT_HANDOFF = "Selection is not content verification. For an optional screenshot workflow, read get_evidence_capture_guide. If mcp-screenshot is connected, inspect its uncropped preview before proposing a crop; otherwise continue native Burp work or let the user capture manually."

internal val EVIDENCE_CAPTURE_GUIDE = buildJsonObject {
    put("version", 2)
    put("optional", true)
    put("standalone", "Both servers work independently. The screenshot companion is OPTIONAL and is never required for Burp startup, investigation, native request/response retrieval, Organizer, or other Burp tools. Only use the companion workflow for an explicit image/screenshot request when its tools are available; never prompt installation for unrelated work.")
    put("architecture", "AI-client orchestration: this Burp server prepares native evidence and local UI selection; the separate mcp-screenshot server owns OS capture, preview, crop confirmation, profiles and PNG/JSON storage. Burp does not connect to or launch another MCP server.")
    put("prerequisites", "Discover tools on both connected servers by name/description; connector prefixes vary. mcp-screenshot 0.8.2+ exposes get_capture_guide. Read that guide as the authority for capture parameters. Burp cannot detect whether the companion is connected. If absent and a screenshot is requested, offer manual OS capture or an available screenshot tool. Continue native Burp work normally; do not return a missing-dependency failure or demand installation. Never claim an image was saved or install/launch services silently.")
    put("repeater", "Call list_repeater_tabs; resolve the requested exact title to the returned session tabId, then select_repeater_tab(tabId, expectedTitle). Title 20 is not array index 20. get_repeater_tab_history can describe observed editor states, but is not the complete native back/forward history. For latest, verify the displayed state; do not resend a request merely to obtain a screenshot.")
    put("organizer", "List native Organizer IDs with list_organizer_items and inspect relevant items by ID. Select EACH with select_organizer_item. The item must be uniquely visible in the current collection/Contents and filters; selection does not change collection/filter and saving an exchange does not prove collection membership. PRECONDITION_FAILED means stop, adjust the UI manually or with an available UI tool, and verify again; never label the currently visible screenshot as the requested item.")
    put("other_tabs", "Use select_burp_tool for a top-level tab such as MCP, PROXY or REPEATER. It does not select inner rows. For a request like the logo in MCP, select MCP then locate the logo visually in the screenshot. In Read-only mode navigation tools are omitted: ask the user to select the content; do not switch catalog/security settings just for a screenshot.")
    put("verification", "selected/visible and SELECTION_RECHECKED_ON_EDT verify UI selection only. contentVerified remains false. They do not establish rendering, foreground focus, request/response identity, or a saved PNG. Match actual rendered content in the companion preview to the requested native ID/tab/context; if navigation and pixels disagree, stop and resolve it.")
    put("preview", "On mcp-screenshot first call get_capture_status to check permissions/version, then list_windows(detail=full), select the intended Burp OS window and copy selection_token to expected_window_token. Call capture_window(window_id, expected_window_token, persist=false, include_image=true) without region/profile. Actually view the image. OS window IDs differ from Burp native item IDs/tab IDs. If the client cannot see images or control navigation, use manual selection instead of guessing.")
    put("dynamic_crop", "Compute a fresh useful-content crop for every payload/response/item. Normalize pixel bounds by the returned image width/height, top-left origin; do not use logical macOS points. In the SAME companion connection, call select_capture_region with window_id/token, request, suggestion={region,source_sha256,reason}. Keep that connection alive: previews expire after five minutes. Omit name/profile for dynamic crops; fixed geometric profiles do not adapt to content length. Do not automatically save a burp-repeater profile. Hidden/scrolling content is not included.")
    put("companion_compatibility", "Check the connected companion version with get_capture_status and read its get_capture_guide when available (0.8.2+). The connected server's guide is authoritative; do not infer runtime behavior from a checkout, rebuilt binary or this Burp version. In mcp-screenshot 0.8.3, Capturar e salvar saves the approved crop of the exact frozen preview and preserves its original captured_at. Older versions may take a new screenshot after confirmation. For unknown versions or missing guidance, do not assume either behavior: obtain an explicit preview/confirmation workflow supported by that server, or ask the user to capture manually, then inspect the saved PNG.")
    put("confirmation", "Allow the user to adjust/confirm in the selector, with at least 330000 ms client timeout per interactive step. Do not auto-confirm. With companion 0.8.3, changing the Burp response while the dialog is open does not update the saved image: it still contains the previously reviewed preview. Follow companion_compatibility for other versions. Only metadata.persisted=true means saved; region-only means selection confirmed. Do not capture again after a successful save. Retrieve get_evidence(id, include_image=true) and inspect the saved result before claiming completion.")
    put("batch", "Keep one case_id; select and verify EACH item, recalculate dynamic crops, and pass earlier evidence IDs in reject_same_as (up to 20). DUPLICATE_CAPTURE saves nothing. Never remove the guard merely to make a batch succeed. Different hashes are not proof of correct items. Mark wrong saved captures rejected/needs_recapture with review_evidence and report missing items honestly; preserve originals.")
    put("recovery", buildJsonObject {
        put("stale_window", "Refresh list_windows and inspect a new uncropped preview before suggesting another crop; never reuse a token after the window identity or bounds change.")
        put("content_changed", "For companion 0.8.3, use Atualizar prévia to obtain current pixels; it discards the previous crop and fixed-profile name for a new review. Alternatively cancel/reopen the selector after inspecting a new uncropped preview. Recheck the requested Burp tab/item and visible response, then adjust/confirm again. Never save the old frozen preview while describing it as the updated response. If refresh is unavailable, follow the connected companion guide instead of assuming it supports that button.")
        put("stale_preview", "Keep the same companion connection. If the preview expired or was evicted, inspect a new preview or use manual select_capture_region without suggestion. Never invent a source_sha256.")
        put("unavailable_image", "In companion 0.8.3, local manual select_capture_region supports previews above the MCP inline image limit. For other versions, check the connected guide before offering this recovery; older selectors may share the inline limit. If an image cannot be viewed, use supported manual selection without suggestion. Do not infer crop coordinates from metadata or resized chat images.")
        put("cancel_or_timeout", "Cancellation or timeout is not capture success. A client timeout may leave the companion running: reconcile its result or saved evidence before retrying, to avoid duplicate files or competing selectors. Do not auto-confirm or blindly repeat capture.")
        put("selection_only", "A region-only result has not saved evidence. Save only when requested, using the returned approved region after refreshing the window token and verifying that the intended content and geometry still match. If they changed, obtain a fresh preview and confirmation.")
        put("missing_tools", "After an upgrade, reload the Burp extension and reconnect the relevant MCP clients to refresh discovery. A rebuilt JAR or companion binary does not update an already running process. Do not change security profiles to expose navigation in Read-only.")
    })
    put("traceability", "Report actual screenshot IDs/paths returned by the companion together with native Burp IDs/tab title. A caller-supplied exchange_id is an association, not verified identity. Reviews are screenshot-quality decisions, not vulnerability validation. Keep captures local unless sharing is authorized; do not infer permission to publish credentials or target data.")
}

internal fun Server.registerEvidenceCaptureGuide() {
    mcpTool(
        "get_evidence_capture_guide",
        "Read the Burp-to-mcp-screenshot workflow: select Repeater/Organizer/tool content, verify pixels, request dynamic crop confirmation, and save traceable evidence. Read-only guidance; no capture, navigation, target traffic or peer MCP connection. Available in all catalogs.",
        READ_ONLY_TOOL
    ) { EVIDENCE_CAPTURE_GUIDE.toString() }
}
